H.background();
const sel = Math.round(P.kind);
const v = H.plot2d({ xMin: -5, xMax: 5, yMin: -2, yMax: 8 });
v.grid(); v.axes();
const c = 1;
let title, caption, val;
if (sel <= 1) {
  title = "Removable discontinuity (a hole)";
  caption = "f(x) = (x^2 - 1)/(x - 1) = x + 1 except at x=1 -- a single point is missing";
  v.fn(x => Math.abs(x - c) < 0.02 ? NaN : x + 1, { color: H.colors.accent, width: 3 });
  v.circle(c, c + 1, 7, { stroke: H.colors.warn, width: 2, fill: H.colors.bg });
  val = "limit = " + (c + 1).toFixed(0) + ", but f(1) is undefined";
} else if (sel === 2) {
  title = "Jump discontinuity";
  caption = "Left and right limits exist but disagree -- the graph leaps at x=1";
  v.fn(x => x < c ? x + 1 : NaN, { color: H.colors.accent, width: 3 });
  v.fn(x => x >= c ? x + 4 : NaN, { color: H.colors.accent2, width: 3 });
  v.dot(c, c + 1, { r: 6, fill: H.colors.bg });
  v.circle(c, c + 1, 6, { stroke: H.colors.accent, width: 2, fill: H.colors.bg });
  v.dot(c, c + 4, { r: 6, fill: H.colors.accent2 });
  val = "left limit = 2, right limit = 5  (jump = 3)";
} else {
  title = "Infinite discontinuity (asymptote)";
  caption = "The function diverges near x=1 -- no limit exists there";
  v.fn(x => { const d = x - c; return Math.abs(d) < 0.05 ? NaN : Math.min(Math.max(1 / d + 3, -2), 8); }, { color: H.colors.accent, width: 3 });
  v.line(c, -2, c, 8, { color: H.colors.warn, width: 2, dash: [6, 5] });
  val = "limit -> +/- infinity";
}
